const movieRaw = $('Query GraphQL').item.json;
const seriesRaw = $('Query GraphQL Series').item.json;
const movieUni = movieRaw?.data?.homepageUniverses || {};
const seriesUni = seriesRaw?.data?.homepageUniverses || {};

function mapProduct(p) {
  return {
    id: String(p.id),
    title: p.title || '',
    year: p.yearOfProduction || null,
    rating: typeof p.rating === 'number' ? p.rating : null,
    wishCount: p.stats?.wishCount ?? 0,
    ratingCount: p.stats?.ratingCount ?? 0,
    poster: p.medias?.picture || '',
    url: p.url ? 'https://www.senscritique.com' + p.url : '',
    scouts: p.scoutsAverage?.average ?? null,
    scoutsCount: p.scoutsAverage?.count ?? 0
  };
}

const movieReleases = (movieUni.newRelease || []).map(mapProduct);
const movieAwaitedSel = (movieUni.selections || []).find(s => s.label === 'film_attendu');
let movieAwaited = (movieAwaitedSel?.products || []).map(mapProduct);

const seriesReleasesSel = (seriesUni.selections || []).find(s => s.label === 'nouvelle_serie');
const seriesReleases = (seriesReleasesSel?.products || []).map(mapProduct);
const seriesAwaitedSel = (seriesUni.selections || []).find(s => s.label === 'serie_attendue');
let seriesAwaited = (seriesAwaitedSel?.products || []).map(mapProduct);

// Fusionne les dates de sortie recuperees par le node Query Dates
const datesRaw = items[0]?.json?.data || {};
const dateById = {};
for (const key of Object.keys(datesRaw)) {
  const p = datesRaw[key];
  if (p?.id) dateById[String(p.id)] = p.dateReleaseOriginal || p.frenchReleaseDate || null;
}
const today = new Date().toISOString().slice(0, 10);
function attachDatesAndFilter(list) {
  return list.map(f => ({ ...f, releaseDate: dateById[f.id] || null }))
    .filter(f => !f.releaseDate || f.releaseDate >= today);
}
movieAwaited = attachDatesAndFilter(movieAwaited);
seriesAwaited = attachDatesAndFilter(seriesAwaited);

return [{ json: {
  movies: { releases: movieReleases, awaited: movieAwaited },
  series: { releases: seriesReleases, awaited: seriesAwaited },
  fetchedAt: new Date().toISOString()
} }];

const raw = items[0].json;
const p = raw?.data?.product || null;
if (!p) return [{ json: { error: 'not_found' } }];
const names = l => (l || []).map(x => x.name).filter(Boolean);
const dirs = names(p.directors).length ? names(p.directors) : names(p.creators);
return [{ json: {
  id: String(p.id),
  title: p.title || '',
  year: p.yearOfProduction || null,
  rating: typeof p.rating === 'number' ? p.rating : null,
  url: p.url ? 'https://www.senscritique.com' + p.url : '',
  directors: dirs,
  scouts: p.scoutsAverage?.average ?? null,
  scoutsCount: p.scoutsAverage?.count ?? 0,
  synopsis: p.synopsis || '',
  actors: (p.actors || []).slice(0, 8).map(a => ({ name: a.name || '', role: a.role || '' })),
  backdrop: p.medias?.backdrop || p.medias?.picture || '',
  videoId: (p.medias?.videos && p.medias.videos[0]) ? p.medias.videos[0].id : null
} }];

const body = $('Webhook Rating').item.json.body || {};
const wantUniverse = body.type === 'series' ? 4 : 1;
const accents = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(accents, '').replace(/[^a-z0-9]+/g, ' ').trim();
const yearOf = p => String(p.dateReleaseOriginal || p.dateRelease || '').slice(0, 4);

const raw = items[0].json;
const products = ((raw && raw.data && raw.data.searchAutocomplete && raw.data.searchAutocomplete.items) || [])
  .map(i => i.product).filter(p => p && p.universe === wantUniverse);
const wantTitle = norm(body.title);
const candidates = products.filter(p => norm(p.title) === wantTitle || norm(p.originalTitle) === wantTitle);

let hit = null;
if (body.year) {
  const y = Number(body.year);
  hit = candidates.find(p => yearOf(p) === String(y))
    || candidates.find(p => Math.abs(Number(yearOf(p)) - y) <= 1)
    || (candidates.length === 1 ? candidates[0] : null);
} else {
  hit = candidates[0] || null;
}
// repli : titres qui different par un sous-titre (ex: "Dune - Premiere partie" vs "Dune"), annee identique exigee
if (!hit && body.year) {
  const ys = String(Number(body.year));
  hit = products.find(p => yearOf(p) === ys && norm(p.title).length >= 3
    && (wantTitle.startsWith(norm(p.title) + ' ') || norm(p.title).startsWith(wantTitle + ' '))) || null;
}
if (!hit) return [{ json: { found: false } }];
return [{ json: {
  found: true,
  id: String(hit.id),
  title: hit.title,
  year: yearOf(hit) || null,
  rating: typeof hit.rating === 'number' ? hit.rating : null,
  scouts: hit.scoutsAverage?.average ?? null,
  scoutsCount: hit.scoutsAverage?.count ?? 0,
  url: hit.url ? 'https://www.senscritique.com' + hit.url : ''
} }];
